# Orthogonal multi-dimensional retrieval
def retrieve(query, dimensions=['user', 'agent', 'project']):
    results = {}
    for dim in dimensions:
        dim_results = search(index[dim], query, id=user_id if dim=='user' else None)
        results[dim] = dim_results
    # Merge with weighting
    return merge_results(results, weights={'user': 0.5, 'agent': 0.3, 'project': 0.2})

